def solve():
    # Board size
    N = 6

    # Fixed assignments
    fixed = {
        0: 0,
        3: 17,
        6: 24,
        17: 30,
        19: 6,
        29: 25,
        32: 21,
        34: 23
    }

    # Knight moves
    moves = [
        (1, 2), (1, -2), (-1, 2), (-1, -2),
        (2, 1), (2, -1), (-2, 1), (-2, -1)
    ]

    def get_neighbors(cell):
        r, c = divmod(cell, N)
        res = []
        for dr, dc in moves:
            nr, nc = r + dr, c + dc
            if 0 <= nr < N and 0 <= nc < N:
                res.append(nr * N + nc)
        return res

    # Precompute neighbors
    adj = {i: get_neighbors(i) for i in range(N * N)}

    # Backtracking
    tour = [None] * (N * N)
    used = [False] * (N * N)

    def backtrack(step):
        if step == N * N:
            return True

        if step in fixed:
            cell = fixed[step]
            if used[cell]:
                return False
            if step > 0:
                prev_cell = tour[step - 1]
                if cell not in adj[prev_cell]:
                    return False

            tour[step] = cell
            used[cell] = True
            if backtrack(step + 1):
                return True
            used[cell] = False
            tour[step] = None
            return False
        else:
            prev_cell = tour[step - 1]
            for next_cell in adj[prev_cell]:
                if not used[next_cell]:
                    # Check if next_cell is already fixed for another step
                    # Wait, the fixed values are for specific steps.
                    # If next_cell is in fixed.values(), it can only be used at the corresponding step.
                    # Let's check if next_cell is a fixed value for a *different* step.
                    is_fixed_elsewhere = False
                    for s, c in fixed.items():
                        if c == next_cell and s != step:
                            is_fixed_elsewhere = True
                            break
                    if is_fixed_elsewhere:
                        continue

                    tour[step] = next_cell
                    used[next_cell] = True
                    if backtrack(step + 1):
                        return True
                    used[next_cell] = False
                    tour[step] = None
            return False

    if backtrack(0):
        return tour
    else:
        return None

print(solve())
